package com.blackice.bc1.editor;
import org.junit.Test;
import static org.junit.Assert.*;
public class TransformEditsTest {
 @Test public void clockwiseWrapAndMultipleTurns(){float angle=359;angle+=TransformEdits.pointerDelta(179,-179);assertEquals(361,angle,0);for(int i=0;i<8;i++)angle+=TransformEdits.pointerDelta(-90,0);assertEquals(1081,angle,0);assertEquals(-2,TransformEdits.pointerDelta(-179,179),0);}
 @Test public void independentAndProportionalScale(){assertArrayEquals(new float[]{3,1.5f},TransformEdits.dimensions(2,1,true,3,true),.0001f);assertArrayEquals(new float[]{3,1},TransformEdits.dimensions(2,1,true,3,false),.0001f);assertArrayEquals(new float[]{1,.5f},TransformEdits.dimensions(2,1,true,1,true),.0001f);assertArrayEquals(new float[]{2,1},TransformEdits.dimensions(2,.5f,false,1,false),.0001f);}
 @Test public void unsafeScaleRejected(){for(float v:new float[]{0,-1,Float.NaN,Float.POSITIVE_INFINITY,10000})try{TransformEdits.dimensions(1,1,true,v,true);fail("Invalid scale "+v);}catch(IllegalArgumentException expected){}}
 @Test public void oldScaleAnimationRetainedAndNewChannelsRoundTrip()throws Exception{EditProject p=new EditProject();EditProject.Overlay o=new EditProject.Overlay();o.text="Scale";o.endMs=3000;o.aspect=.5f;o.motion.put(Motion.SCALE,new Motion.Key(0,1));o.motion.put(Motion.SCALE,new Motion.Key(2000,2));p.overlays.add(o);float before=TransformMath.of(o,1000).scale;TransformEdits.materialize(o.motion,Motion.WIDTH,o.widthScale,o.aspect);TransformEdits.materialize(o.motion,Motion.HEIGHT,o.heightScale,o.aspect);assertEquals(before,TransformMath.of(o,1000).scale,0);assertEquals(.5f,TransformMath.of(o,1000).aspect,0);o.motion.put(Motion.WIDTH,new Motion.Key(1000,3));o.motion.put(Motion.HEIGHT,new Motion.Key(1000,1.5f));EditProject restored=ProjectStore.decode(ProjectStore.encode(p));TransformMath.Transform t=TransformMath.of(restored.overlays.get(0),1000);assertEquals(3,t.scale,0);assertEquals(1.5f,t.scale*t.aspect,0);assertEquals(2,o.motion.curves.get(Motion.SCALE).size());}
 @Test public void rotationKeepsTurnsAndDirectionAfterReopen()throws Exception{for(int sign:new int[]{1,-1}){EditProject p=new EditProject();EditProject.Overlay o=new EditProject.Overlay();o.text="Spin";o.endMs=3000;Motion.Key first=new Motion.Key(0,0);Keyframes.ease(first,0);o.motion.put(Motion.ROTATION,first);o.motion.put(Motion.ROTATION,new Motion.Key(2000,sign*720));p.overlays.add(o);o=ProjectStore.decode(ProjectStore.encode(p)).overlays.get(0);assertEquals(sign*180,TransformMath.of(o,500).rotation,.01);assertEquals(sign*360,TransformMath.of(o,1000).rotation,.01);assertEquals(sign*720,TransformMath.of(o,2000).rotation,.01);}}
 @Test public void legacyTenChannelProjectStillLoads()throws Exception{EditProject p=new EditProject();EditProject.Overlay o=new EditProject.Overlay();o.text="Legacy";o.aspect=1.7f;o.scale=.8f;p.overlays.add(o);org.json.JSONObject json=new org.json.JSONObject(ProjectStore.encode(p));json.put("schema",5);org.json.JSONObject layer=json.getJSONArray("overlays").getJSONObject(0);layer.remove("widthScale");layer.remove("heightScale");org.json.JSONArray curves=layer.getJSONArray("motion");curves.remove(11);curves.remove(10);o=ProjectStore.decode(json.toString()).overlays.get(0);assertEquals(.8f,TransformMath.of(o,0).scale,0);assertEquals(1.7f,TransformMath.of(o,0).aspect,.0001);}
}
